namespace {using namespace staged_lm;std::filesystem::path arg(int n,char**v,const std::string&k){for(int i=1;i+1<n;++i)if(v[i]==k)return v[i+1];throw std::runtime_error("missing "+k);}int iv(const std::map<std::string,std::string>&m,const std::string&k){return std::stoi(m.at(k));}float fv(const std::map<std::string,std::string>&m,const std::string&k){return std::stof(m.at(k));}PoseShapeCameraInput camera(const std::filesystem::path&f,const std::map<std::string,std::string>&m,const std::vector<float>&p,const std::string&c){int n=iv(m,c+"_count");PoseShapeCameraInput x;x.pose.camera=c;x.pose.parameters={p.begin(),p.begin()+75};x.pose.point_count=n;x.pose.left_hand_pose=read_float32_file(f/(c+"_left_hand_pose.f32"),45);x.pose.right_hand_pose=read_float32_file(f/(c+"_right_hand_pose.f32"),45);x.pose.scale=read_float32_file(f/(c+"_scale.f32"),1)[0];x.pose.selected_posedirs=read_float32_file(f/(c+"_selected_posedirs.f32"),486*n*3);x.pose.selected_lbs_weights=read_float32_file(f/(c+"_selected_lbs_weights.f32"),n*55);x.pose.targets=read_float32_file(f/(c+"_targets.f32"),n*2);x.pose.image_width=iv(m,"image_width");x.pose.image_height=iv(m,"image_height");x.selected_base_v_shaped=read_float32_file(f/(c+"_selected_base_v_shaped.f32"),n*3);x.selected_beta_shapedirs=read_float32_file(f/(c+"_selected_beta_shapedirs.f32"),n*3*10);return x;}void wc(const std::filesystem::path&o,const std::string&c,const PoseShapeCameraNormalEquations&r){write_float32_file(o/(c+"_point_weights.f32"),r.active.point_weights);write_float32_file(o/(c+"_row_scales.f32"),r.active.row_scales);write_float32_file(o/(c+"_weighted_residual.f32"),r.active.weighted_residual);write_float32_file(o/(c+"_weighted_J_active.f32"),r.active.weighted_jacobian_active);write_float32_file(o/(c+"_weighted_J_beta.f32"),r.weighted_jacobian_beta);write_float64_file(o/(c+"_H_aa.f64"),r.active.hessian_active);write_float64_file(o/(c+"_H_ab.f64"),r.h_active_beta);write_float64_file(o/(c+"_H_bb.f64"),r.h_beta_beta);write_float64_file(o/(c+"_g_a.f64"),r.active.gradient_active);write_float64_file(o/(c+"_g_b.f64"),r.g_beta);}}
int main(int argc,char**argv){try{auto f=arg(argc,argv,"--fixture"),o=arg(argc,argv,"--output");auto m=read_key_value_file(f/"fixture_meta.txt");auto p=read_float32_file(f/"parameters.f32",85),base=read_float32_file(f/"base_joints.f32",165),basis=read_float32_file(f/"d_joints_d_beta.f32",1650);std::vector<float>z(p.begin()+75,p.end());auto shape=evaluate_shape_value(z,fv(m,"beta_abs_limit"),base,basis,55);std::vector<float>db(10),dj(1650);for(int b=0;b<10;++b)db[b]=fv(m,"beta_abs_limit")*(1-shape.tanh_latent[b]*shape.tanh_latent[b]);for(int i=0;i<165;++i)for(int b=0;b<10;++b)dj[i*10+b]=basis[i*10+b]*db[b];PoseModelInput model{shape.joints,read_int64_file(f/"parents.i64",55)};auto i2=camera(f,m,p,"cam2"),i4=camera(f,m,p,"cam4");auto v2=evaluate_dynamic_vertices(i2.selected_base_v_shaped,i2.selected_beta_shapedirs,shape.beta,i2.pose.point_count),v4=evaluate_dynamic_vertices(i4.selected_base_v_shaped,i4.selected_beta_shapedirs,shape.beta,i4.pose.point_count);auto j2=evaluate_pose_shape_camera_with_jacobian(model,i2,v2,dj,db),j4=evaluate_pose_shape_camera_with_jacobian(model,i4,v4,dj,db);PoseShapeNormalEquationConfig cfg;cfg.charbonnier_eps=fv(m,"charbonnier_eps");cfg.cam2_alpha_per_point=fv(m,"cam2_alpha");cfg.cam4_alpha_per_point=fv(m,"cam4_alpha");cfg.pose_anchor_scale=fv(m,"pose_anchor_scale");cfg.shape_anchor_scale=fv(m,"shape_anchor_scale");auto r=build_pose_shape_normal_equations(j2,j4,p,read_float32_file(f/"body_pose_anchor.f32",63),read_float32_file(f/"beta_anchor.f32",10),cfg);std::filesystem::create_directories(o);wc(o,"cam2",r.cam2);wc(o,"cam4",r.cam4);std::pair<const char*,const std::vector<double>*>a[]={{"A_data",&r.a_data},{"B_data",&r.b_data},{"C_data",&r.c_data},{"g_frame_data",&r.g_frame_data},{"g_beta_data",&r.g_beta_data},{"A_pose_prior",&r.a_pose_prior},{"g_pose_prior",&r.g_pose_prior},{"C_shape_prior",&r.c_shape_prior},{"g_shape_prior",&r.g_shape_prior},{"A_final",&r.a_final},{"B_final",&r.b_final},{"C_final",&r.c_final},{"g_frame_final",&r.g_frame_final},{"g_beta_final",&r.g_beta_final},{"H_dense_structured",&r.h_dense_structured},{"g_dense_structured",&r.g_dense_structured}};for(auto [n,v]:a)write_float64_file(o/(std::string(n)+".f64"),*v);write_key_value_file(o/"pose_shape_ne_meta.txt",{{"axes.A","frame_param,frame_param"},{"axes.B","frame_param,beta"},{"axes.C","beta,beta"},{"cam2_hab_ms",std::to_string(r.cam2.h_ab_ms)},{"cam2_hbb_ms",std::to_string(r.cam2.h_bb_ms)},{"cam4_hab_ms",std::to_string(r.cam4.h_ab_ms)},{"cam4_hbb_ms",std::to_string(r.cam4.h_bb_ms)},{"scatter_accumulate_ms",std::to_string(r.scatter_accumulate_ms)},{"pose_prior_ms",std::to_string(r.pose_prior_ms)},{"shape_prior_ms",std::to_string(r.shape_prior_ms)},{"total_ms",std::to_string(r.total_ms)}});std::cout<<"POSE_SHAPE_NE_REFERENCE_WRITTEN\n";return 0;}catch(const std::exception&e){std::cerr<<e.what()<<'\n';return 1;}}
